import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"SuperKernel","link":"/guide/programming_guide/advanced_programming/super_kernel/principles"},{"text":"核函数（Kernel）直调算子额外适配说明","link":"/guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.md","filePath":"guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.md","outlineHeaders":[{"level":2,"title":"SuperKernel与普通核函数（Kernel）的区别","slug":"SuperKernel与普通核函数（Kernel）的区别","link":"#SuperKernel与普通核函数（Kernel）的区别"},{"level":3,"title":"普通核函数（Kernel）入口函数","slug":"普通核函数（Kernel）入口函数","link":"#普通核函数（Kernel）入口函数"},{"level":3,"title":"SuperKernel入口函数","slug":"SuperKernel入口函数","link":"#SuperKernel入口函数"},{"level":2,"title":"SuperKernel适配规则","slug":"SuperKernel适配规则","link":"#SuperKernel适配规则"},{"level":3,"title":"SK子函数编写规则","slug":"SK子函数编写规则","link":"#SK子函数编写规则"},{"level":4,"title":"规则1：函数签名格式","slug":"规则1：函数签名格式","link":"#规则1：函数签名格式"},{"level":4,"title":"规则2：Kernel Type标识与原global函数保持一致","slug":"规则2：Kernel-Type标识与原global函数保持一致","link":"#规则2：Kernel-Type标识与原global函数保持一致"},{"level":4,"title":"规则3：定义参数结构体","slug":"规则3：定义参数结构体","link":"#规则3：定义参数结构体"},{"level":4,"title":"规则4：可选添加SkSystemArgs参数","slug":"规则4：可选添加SkSystemArgs参数","link":"#规则4：可选添加SkSystemArgs参数"},{"level":4,"title":"规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口","slug":"规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口","link":"#规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口"},{"level":4,"title":"规则6：逻辑与global函数一致","slug":"规则6：逻辑与global函数一致","link":"#规则6：逻辑与global函数一致"},{"level":3,"title":"SK_BIND绑定规则","slug":"SK_BIND绑定规则","link":"#SK_BIND绑定规则"},{"level":4,"title":"规则7：使用SK_BIND宏绑定","slug":"规则7：使用SK_BIND宏绑定","link":"#规则7：使用SK_BIND宏绑定"},{"level":2,"title":"完整适配示例","slug":"完整适配示例","link":"#完整适配示例"},{"level":3,"title":"原始普通核函数（Kernel）","slug":"原始普通核函数（Kernel）","link":"#原始普通核函数（Kernel）"},{"level":3,"title":"SuperKernel适配版本","slug":"SuperKernel适配版本","link":"#SuperKernel适配版本"},{"level":2,"title":"适配步骤总结","slug":"适配步骤总结","link":"#适配步骤总结"},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项"},{"level":3,"title":"参数结构体定义注意事项","slug":"参数结构体定义注意事项","link":"#参数结构体定义注意事项"},{"level":3,"title":"系统参数使用注意事项","slug":"系统参数使用注意事项","link":"#系统参数使用注意事项"},{"level":3,"title":"绑定限制","slug":"绑定限制","link":"#绑定限制"},{"level":3,"title":"绑定掩码参数说明","slug":"绑定掩码参数说明","link":"#绑定掩码参数说明"},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题"}],"lastUpdated":1788399502000}'),c={name:"guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.md"};function e(t,s,o,d,i,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>核函数（Kernel）直调算子额外适配说明</h1><p>对于使用<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>方式开发的Ascend C算子，除了遵循<a href="operator_adaptation.html">算子适配说明</a>中的通用约束外，还需要在算子核函数（Kernel）入口侧增加SuperKernel入口函数。本文档介绍具体的适配方法。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>核函数（Kernel）直调算子目前仅支持在npugraph_ex后端进入SuperKernel，不支持GE图模式。</p></div><h2 id="SuperKernel与普通核函数（Kernel）的区别">SuperKernel与普通核函数（Kernel）的区别<a class="header-anchor" href="#SuperKernel与普通核函数（Kernel）的区别">​</a></h2><h3 id="普通核函数（Kernel）入口函数">普通核函数（Kernel）入口函数<a class="header-anchor" href="#普通核函数（Kernel）入口函数">​</a></h3><ul><li>函数签名：<code>__global__ __vector__ void func(参数列表)</code></li><li>参数直接作为函数参数传递。</li><li>直接调用即可。</li></ul><h3 id="SuperKernel入口函数">SuperKernel入口函数<a class="header-anchor" href="#SuperKernel入口函数">​</a></h3><ul><li>函数签名：<code>__sk__ __vector__ void func(const ArgsStruct *args, sk::SkSystemArgs *sysArgs)</code></li><li>参数通过结构体指针传递，需要用户定义参数结构体并封装入参。</li><li>可选添加<code>sk::SkSystemArgs *sysArgs</code>参数，用于获取系统信息（如block num）。</li><li>需要与普通核函数（Kernel）通过SK_BIND宏绑定。</li></ul><h2 id="SuperKernel适配规则">SuperKernel适配规则<a class="header-anchor" href="#SuperKernel适配规则">​</a></h2><h3 id="SK子函数编写规则">SK子函数编写规则<a class="header-anchor" href="#SK子函数编写规则">​</a></h3><h4 id="规则1：函数签名格式">规则1：函数签名格式<a class="header-anchor" href="#规则1：函数签名格式">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">function_name_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">)</span>
</code></pre></div><blockquote><p><strong>注意</strong>：只有<code>__sk__</code>是强约束，必须出现在函数签名中。</p></blockquote><h4 id="规则2：Kernel-Type标识与原global函数保持一致">规则2：Kernel Type标识与原global函数保持一致<a class="header-anchor" href="#规则2：Kernel-Type标识与原global函数保持一致">​</a></h4><ul><li>如果原global函数使用<code>__cube__</code>，则SK子函数也必须使用<code>__cube__</code>。</li><li>如果原global函数使用<code>__vector__</code>，则SK子函数也必须使用<code>__vector__</code>。</li><li>如果原global函数是<code>__mix__(c, v)</code>，则SK子函数也必须使用<code>__mix__(c, v)</code>。</li></ul><p><strong>示例</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 原global函数为cube类型</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="c1">// SK子函数也需要cube标识</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">);</span>

<span class="n">SK_BIND</span><span class="p">(</span><span class="n">func</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">func_sk</span><span class="p">);</span>

<span class="c1">// 原global函数为vector类型</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_vec</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="c1">// SK子函数也需要vector标识</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_vec_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">);</span>

<span class="n">SK_BIND</span><span class="p">(</span><span class="n">func_vec</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">func_vec_sk</span><span class="p">);</span>

<span class="c1">// 原global函数为mix类型</span>
<span class="n">__global__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="c1">// SK子函数需要mix标识</span>
<span class="n">__sk__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">);</span>

<span class="n">SK_BIND</span><span class="p">(</span><span class="n">func_mix</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">func_mix_sk</span><span class="p">);</span>

<span class="c1">// 原global函数为mix(1, 0)类型</span>
<span class="n">__global__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix_10</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="c1">// SK子函数需要cube标识</span>
<span class="n">__sk__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix_10_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">);</span>

<span class="n">SK_BIND</span><span class="p">(</span><span class="n">func_mix_10</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">func_mix_10_sk</span><span class="p">);</span>

<span class="c1">// 原global函数为mix(0, 1)类型</span>
<span class="n">__global__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix_01</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">);</span>
<span class="c1">// SK子函数需要vector标识</span>
<span class="n">__sk__</span><span class="w"> </span><span class="nf">__mix__</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_mix_01_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">);</span>

<span class="n">SK_BIND</span><span class="p">(</span><span class="n">func_mix_01</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">func_mix_01_sk</span><span class="p">);</span>
</code></pre></div><h4 id="规则3：定义参数结构体">规则3：定义参数结构体<a class="header-anchor" href="#规则3：定义参数结构体">​</a></h4><p>用户需要根据原global函数的实际参数定义一个结构体来封装所有入参：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 示例：假设原global函数为</span>
<span class="c1">// __global__ __vector__ void my_kernel(GM_ADDR x, GM_ADDR y, uint32_t length, int16_t flag)</span>
<span class="c1">// 则对应的参数结构体定义如下</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">MyArgs</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 第一个参数</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 第二个参数</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">length</span><span class="p">;</span><span class="w">                </span><span class="c1">// 第三个参数</span>
<span class="w">    </span><span class="k">alignas</span><span class="p">(</span><span class="mi">4</span><span class="p">)</span><span class="w"> </span><span class="kt">int16_t</span><span class="w"> </span><span class="n">flag</span><span class="p">;</span><span class="w">        </span><span class="c1">// 第四个参数（小于4字节，需使用alignas(4)）</span>
<span class="p">};</span>
</code></pre></div><blockquote><p><strong>注意</strong>：</p><ul><li>结构体必须根据用户实际算子核函数（Kernel）（global函数）的参数进行定义，不要直接复制示例中的字段名。</li><li>结构体字段必须按原函数参数顺序排列。</li><li>对于size小于4字节的类型（如<code>int16_t</code>、<code>int8_t</code>、<code>uint16_t</code>、<code>uint8_t</code>），必须使用<code>alignas(4)</code>确保内存对齐（ABI要求）。</li><li>示例：<code>alignas(4) int16_t val;</code>、<code>alignas(4) uint8_t flag;</code></li></ul></blockquote><h4 id="规则4：可选添加SkSystemArgs参数">规则4：可选添加SkSystemArgs参数<a class="header-anchor" href="#规则4：可选添加SkSystemArgs参数">​</a></h4><p>如果原算子使用了<code>AscendC::GetBlockNum()</code>接口，在SK场景下可以通过添加<code>sk::SkSystemArgs *sysArgs</code>参数来获取期望的block num：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 场景一：算子使用了AscendC::GetBlockNum()，需要添加sysArgs参数</span>
<span class="k">template</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">splitNum</span><span class="o">&gt;</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 从系统参数获取block num（替代AscendC::GetBlockNum()）</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">sysArgs</span><span class="o">-&gt;</span><span class="n">skNumBlocks</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 或者使用接口获取</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">sysArgs</span><span class="o">-&gt;</span><span class="n">SkGetNumBlocks</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 后续使用blockNum的代码</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>

<span class="c1">// 场景二：算子未使用AscendC::GetBlockNum()，无需添加sysArgs参数</span>
<span class="k">template</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">splitNum</span><span class="o">&gt;</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 直接使用参数进行计算，无需访问系统信息</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">y</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 后续计算代码</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：</p><ul><li><code>sk::SkSystemArgs *sysArgs</code>参数是可选的，如果算子未使用block num信息，或者<code>sk::SkSystemArgs</code>提供的功能（当前仅支持获取block num），则无需在函数入口传入<code>sysArgs</code>参数，这样可以避免不必要的代码修改。</li><li>用户需要根据实际情况修改原代码中的<code>AscendC::GetBlockNum()</code>调用： <ul><li>直接使用<code>sysArgs-&gt;skNumBlocks</code>访问成员变量。</li><li>或者使用<code>sysArgs-&gt;SkGetNumBlocks()</code>接口获取。</li></ul></li><li>与<code>AscendC::GetBlockNum()</code>的逻辑差异是，MIX 1:2场景中，vector核中的<code>skBlockNum</code>为<code>blockNum * 2</code>。</li></ul></blockquote><h4 id="规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口">规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口<a class="header-anchor" href="#规则5：使用TPipe场景下，需要手动调用DestroyWithoutPipeAll接口">​</a></h4><p>为了优化SK函数之间的同步，若使用了TPipe对象，需要在其自然析构之前调用<code>DestroyWithoutPipeAll()</code>接口主动销毁TPipe（不调用PipeBarrierAll）。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">splitNum</span><span class="o">&gt;</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 使用TPipe场景</span>
<span class="w">    </span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe</span><span class="p">;</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 手动调用接口销毁TPipe，不依赖默认析构函数</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">DestroyWithoutPipeAll</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><h4 id="规则6：逻辑与global函数一致">规则6：逻辑与global函数一致<a class="header-anchor" href="#规则6：逻辑与global函数一致">​</a></h4><p>SK子函数内部的逻辑实现必须与原global函数完全一致，包括数据初始化、计算处理、结果输出等所有后续逻辑。确保SK子函数在功能上与原global函数完全等价。</p><h3 id="SK_BIND绑定规则">SK_BIND绑定规则<a class="header-anchor" href="#SK_BIND绑定规则">​</a></h3><h4 id="规则7：使用SK_BIND宏绑定">规则7：使用SK_BIND宏绑定<a class="header-anchor" href="#规则7：使用SK_BIND宏绑定">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">SK_BIND</span><span class="p">(</span><span class="n">original_func</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">sk_func</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">sk_func</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">sk_func</span><span class="o">&lt;</span><span class="mi">2</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">sk_func</span><span class="o">&lt;</span><span class="mi">3</span><span class="o">&gt;</span><span class="p">);</span>
</code></pre></div><p><strong>参数说明</strong>：</p><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>original_func</code></td><td>原global函数，如果是模板函数需要手动实例化</td></tr><tr><td><code>4</code></td><td>掩码参数（uint64_t类型），用于配置SuperKernel特性</td></tr><tr><td><code>sk_func&lt;0&gt;</code> ~ <code>sk_func&lt;3&gt;</code></td><td>最多4个SK子函数，如果是模板函数需要手动实例化</td></tr></tbody></table><p><strong>掩码参数取值</strong>： 1/2/4/8/16分别代表不同bit位上置值的结果，比如8为第4bit置值的结果</p><table><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td>1</td><td>early start wait flag</td></tr><tr><td>2</td><td>early start set flag</td></tr><tr><td>4</td><td>disable_dcci</td></tr><tr><td>8</td><td>disable_batchmode_check</td></tr><tr><td>16</td><td>blockdim_scale_up</td></tr></tbody></table><blockquote><p><strong>注意</strong>：</p><ul><li>SK子函数使用模板参数实例化出多个符号（推荐，代码更简洁）。</li><li>模板参数仅用于实例化出不同的符号，不影响函数逻辑。</li></ul></blockquote><h2 id="完整适配示例">完整适配示例<a class="header-anchor" href="#完整适配示例">​</a></h2><h3 id="原始普通核函数（Kernel）">原始普通核函数（Kernel）<a class="header-anchor" href="#原始普通核函数（Kernel）">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 普通核函数（Kernel）定义</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">totalLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><h3 id="SuperKernel适配版本">SuperKernel适配版本<a class="header-anchor" href="#SuperKernel适配版本">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 原普通核函数（Kernel）保留（用于非SuperKernel场景）</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">totalLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="p">}</span>

<span class="c1">// 规则3：定义参数结构体（根据原global函数的实际参数定义）</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">AddCustomArgs</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第一个参数</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第二个参数</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第三个参数</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="p">;</span><span class="w">           </span><span class="c1">// 对应add_custom的第四个参数</span>
<span class="p">};</span>

<span class="c1">// 定义一个带模板参数的SK子函数</span>
<span class="c1">// 模板参数仅用于实例化出不同的符号，不影响函数逻辑</span>
<span class="k">template</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">splitNum</span><span class="o">&gt;</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">AddCustomArgs</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="w"> </span><span class="cm">/* 可选添加sysArgs参数 */</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 从结构体中获取参数</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">y</span><span class="p">;</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">z</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">totalLength</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 规则6：逻辑与global函数一致</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">totalLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="p">}</span>

<span class="c1">// 规则7：使用SK_BIND绑定</span>
<span class="c1">// 通过指定模板参数实例化出4个不同的符号</span>
<span class="n">SK_BIND</span><span class="p">(</span><span class="n">add_custom</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">2</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">3</span><span class="o">&gt;</span><span class="p">);</span>
</code></pre></div><h2 id="适配步骤总结">适配步骤总结<a class="header-anchor" href="#适配步骤总结">​</a></h2><p><strong>步骤1：保留原global函数</strong></p><p>原有的<code>__global__ __vector__</code>函数保持不变，继续用于非SuperKernel场景。</p><p><strong>步骤2：创建SK子函数</strong></p><ol><li>复制原global函数的代码</li><li>根据原global函数的实际参数定义参数结构体（对于小于4字节的类型使用<code>alignas(4)</code>）</li><li>修改函数签名为<code>__sk__ __vector__ void func_sk(const ArgsStruct *args, sk::SkSystemArgs *sysArgs)</code>（根据原函数的Kernel Type添加对应标识）</li><li>如果算子未使用<code>AscendC::GetBlockNum()</code>，可以省略<code>sk::SkSystemArgs *sysArgs</code>参数</li><li>使用模板参数实例化出多个符号（模板参数仅用于实例化出不同的符号，不影响函数逻辑）</li><li>从结构体中获取参数</li><li>如果使用了<code>AscendC::GetBlockNum()</code>，修改为使用<code>sysArgs-&gt;skNumBlocks</code>或<code>sysArgs-&gt;SkGetNumBlocks()</code></li><li>使用TPipe场景下，需要手动调用<code>DestroyWithoutPipeAll</code>接口销毁TPipe</li><li>保持函数内部逻辑与原global函数完全一致</li></ol><p><strong>步骤3：添加SK_BIND绑定</strong></p><ol><li>使用<code>SK_BIND</code>宏将原global函数与SK子函数绑定</li><li>支持最多4个SK子函数</li><li>第二个参数是掩码（uint64_t类型），用于配置SuperKernel特性： <ul><li><code>16</code>表示blockdim scale up</li><li><code>8</code>表示disable batchmode check</li><li><code>4</code>表示disable dcci</li><li><code>2</code>表示early start set flag</li><li><code>1</code>表示early start wait flag</li></ul></li></ol><h2 id="注意事项">注意事项<a class="header-anchor" href="#注意事项">​</a></h2><h3 id="参数结构体定义注意事项">参数结构体定义注意事项<a class="header-anchor" href="#参数结构体定义注意事项">​</a></h3><ul><li>结构体必须根据用户实际算子核函数（Kernel）（global函数）的参数进行定义，不要直接复制示例中的字段名。</li><li>结构体字段必须按原函数参数顺序排列。</li><li>对于size小于4字节的类型（如<code>int16_t</code>、<code>int8_t</code>、<code>uint16_t</code>、<code>uint8_t</code>），必须使用<code>alignas(4)</code>确保内存对齐（ABI要求）。</li><li>示例：<code>alignas(4) int16_t val;</code>、<code>alignas(4) uint8_t flag;</code>。</li></ul><h3 id="系统参数使用注意事项">系统参数使用注意事项<a class="header-anchor" href="#系统参数使用注意事项">​</a></h3><ul><li><code>sk::SkSystemArgs *sysArgs</code>是可选参数，只有在原算子使用了<code>AscendC::GetBlockNum()</code>接口时才需要添加。</li><li>如果原算子未使用<code>AscendC::GetBlockNum()</code>接口，无需在函数入口传入<code>sysArgs</code>参数，这样可以避免不必要的代码修改。</li><li>如果原算子使用了<code>AscendC::GetBlockNum()</code>接口，可以通过添加<code>sk::SkSystemArgs *sysArgs</code>参数在SK场景下获取期望的block num： <ul><li>直接使用<code>sysArgs-&gt;skNumBlocks</code>访问成员变量。</li><li>或者使用<code>sysArgs-&gt;SkGetNumBlocks()</code>接口获取。</li></ul></li><li>用户需要根据实际情况修改原代码，将<code>AscendC::GetBlockNum()</code>的调用替换为上述两种方式之一。</li><li>与<code>AscendC::GetBlockNum()</code>的逻辑差异是，MIX 1:2场景中，vector核中的<code>skBlockNum</code>为<code>blockNum * 2</code>。</li></ul><h3 id="绑定限制">绑定限制<a class="header-anchor" href="#绑定限制">​</a></h3><ul><li><code>SK_BIND</code>最多支持绑定4个SK子函数。</li><li>SK子函数的模板参数从0开始递增（<code>&lt;0&gt;</code>到<code>&lt;3&gt;</code>）。</li><li>可以根据实际需求绑定少于等于4个函数。</li></ul><h3 id="绑定掩码参数说明">绑定掩码参数说明<a class="header-anchor" href="#绑定掩码参数说明">​</a></h3><p><code>SK_BIND</code>宏的第二个参数是掩码（uint64_t类型），用于配置SuperKernel特性：</p><table><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td>16</td><td>blockdim scale up</td></tr><tr><td>8</td><td>disable batchmode check</td></tr><tr><td>4</td><td>disable dcci</td></tr><tr><td>2</td><td>early start set flag</td></tr><tr><td>1</td><td>early start wait flag</td></tr></tbody></table><h2 id="常见问题">常见问题<a class="header-anchor" href="#常见问题">​</a></h2><p><strong>Q1：为什么要定义参数结构体？</strong></p><p>A：SuperKernel使用结构体传递参数，用户需要根据原global函数的实际参数定义一个结构体来封装所有入参，这样可以实现参数的统一管理和跨split共享。注意结构体定义必须根据用户实际算子核函数（Kernel）（global函数）的参数进行定义，不要直接复制示例中的字段名。</p><p><strong>Q2：为什么小于4字节的类型需要alignas(4)？</strong></p><p>A：这是ABI（Application Binary Interface）的要求，确保内存对齐，避免访问异常或性能问题。</p><p><strong>Q3：SK子函数的逻辑可以与原函数不同吗？</strong></p><p>A：不可以。SK子函数必须与原global函数在获取参数后的所有逻辑保持一致，否则可能导致计算结果错误。</p><p><strong>Q4：如果只需要1个或2个SK子函数怎么办？</strong></p><p>A：可以在<code>SK_BIND</code>中只填写需要的函数数量，例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">SK_BIND</span><span class="p">(</span><span class="n">add_custom</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">);</span>
</code></pre></div><p><strong>Q5：sk::SkSystemArgs参数是必须的吗？</strong></p><p>A：不是必须的。<code>sk::SkSystemArgs *sysArgs</code>参数是可选的，只有算子需要使用该功能时添加，当前仅支持获取block num。</p><p><strong>Q6：原global函数还需要保留吗？</strong></p><p>A：是的，原global函数继续用于非SuperKernel场景，可以同时支持两种部署方式。</p></article></div>`,1)])])}const h=a(c,[["render",e]]);export{g as __pageData,h as default};
